const ws = new WebSocket('ws://127.0.0.1:8083/')
ws.onopen = () => { ws.send('ping') }
ws.onmessage = (ev) => { console.log(ev.data); ws.close() }

const messages = new EventSource('http://127.0.0.1:8765/stream')
messages.onopen = (ev) => { console.log(ev.type) }   // open
messages.onmessage = (ev) => { console.log(ev.data); messages.close() }

const xhr = new XMLHttpRequest()
xhr.onload = () => { console.log('loaded') }
xhr.open('GET', 'http://127.0.0.1:8765/get')
xhr.send()
console.log(xhr.status)  // 200
